package app.dayflow.assistant;
import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.speech.RecognizerIntent;
import androidx.appcompat.app.AppCompatActivity;import com.google.android.material.button.MaterialButton;import com.google.android.material.color.*;
import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.*;

/** In-task native conversation. No daemon, microphone polling, HTTP port or separate account. */
public final class MainActivity extends AppCompatActivity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile boolean closed;private boolean busy;private String resultDate="";private ChatEngine engine;private LinearLayout messages;private ScrollView scroll;private EditText input;private MaterialButton send,voice,undo;private TextView status;private final LinkedHashSet<String> created=new LinkedHashSet<>();private final JSONArray transcript=new JSONArray();
 public void onCreate(Bundle state){
  getDelegate().setLocalNightMode(getIntent().getBooleanExtra("dayflow_dark",false)?androidx.appcompat.app.AppCompatDelegate.MODE_NIGHT_YES:androidx.appcompat.app.AppCompatDelegate.MODE_NIGHT_NO);super.onCreate(state);
  if(!"app.dayflow".equals(getCallingPackage())||getIntent().getIntExtra("dayflow_protocol",0)!=2){Toast.makeText(this,"请更新日栖本体，并从日栖打开AI助手",Toast.LENGTH_LONG).show();finish();return;}
  DynamicColors.applyToActivityIfAvailable(this,new DynamicColorsOptions.Builder().setContentBasedSource(getIntent().getIntExtra("dayflow_seed",0xff386a5c)).build());engine=new ChatEngine(this,getIntent().getStringExtra("dayflow_session"));setResult(RESULT_OK);
  LinearLayout root=column();root.setBackgroundColor(color(com.google.android.material.R.attr.colorSurface));setContentView(root);androidx.core.view.ViewCompat.setOnApplyWindowInsetsListener(root,(v,insets)->{androidx.core.graphics.Insets bars=insets.getInsets(androidx.core.view.WindowInsetsCompat.Type.systemBars()|androidx.core.view.WindowInsetsCompat.Type.ime());root.setPadding(bars.left,bars.top,bars.right,bars.bottom);return androidx.core.view.WindowInsetsCompat.CONSUMED;});
  LinearLayout header=row();header.setPadding(dp(12),0,dp(12),0);header.addView(button("‹",this::finish),new LinearLayout.LayoutParams(dp(48),dp(48)));TextView title=text("AI助手 · "+getIntent().getStringExtra("dayflow_model"),15);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));header.addView(button("新对话",()->{if(busy)return;engine.clear();messages.removeAllViews();while(transcript.length()>0)transcript.remove(transcript.length()-1);bubble("提示","说说你想安排什么。已创建的事项仍保存在日栖。");persist();}),new LinearLayout.LayoutParams(dp(88),dp(48)));root.addView(header);
  scroll=new ScrollView(this);scroll.setFillViewport(true);messages=column();messages.setPadding(dp(16),0,dp(16),dp(16));scroll.addView(messages);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));status=text("",12);status.setPadding(dp(16),dp(4),dp(16),dp(4));root.addView(status);
  LinearLayout tools=row();tools.setPadding(dp(12),0,dp(12),0);undo=button("撤销本次创建",this::undo);undo.setEnabled(false);tools.addView(undo,new LinearLayout.LayoutParams(0,dp(48),1));tools.addView(button(getIntent().getBooleanExtra("dayflow_review_only",false)?"返回人工核验":"查看日程",()->{if(!busy){setResult(RESULT_OK,new Intent().putExtra("dayflow_open_inbox",getIntent().getBooleanExtra("dayflow_review_only",false)).putExtra("dayflow_open_schedule",!getIntent().getBooleanExtra("dayflow_review_only",false)).putExtra("dayflow_open_date",resultDate));finish();}}),new LinearLayout.LayoutParams(0,dp(48),1));root.addView(tools);
  LinearLayout compose=row();compose.setPadding(dp(12),0,dp(12),dp(8));input=new EditText(this);input.setHint("安排日程、查询待办、记录笔记…");input.setTextColor(color(com.google.android.material.R.attr.colorOnSurface));input.setTextSize(getIntent().getIntExtra("dayflow_font_size",17));input.setMinLines(1);input.setMaxLines(4);input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);input.setSaveEnabled(false);compose.addView(input,new LinearLayout.LayoutParams(0,-2,1));voice=button("语音",this::voice);compose.addView(voice,new LinearLayout.LayoutParams(dp(64),dp(48)));send=button("发送",this::send);compose.addView(send,new LinearLayout.LayoutParams(dp(64),dp(48)));root.addView(compose);
  load();if(transcript.length()==0)bubble("提示","直接描述安排即可，创建结果会显示在下方并支持撤销。通知、短信和群聊整理结果先进入收集箱，人工核验后安排。\n对话与按需查询结果会发给你配置的AI；语音由手机识别服务处理，识别后可编辑再发送。");
  String seed=getIntent().getStringExtra("dayflow_seed_message");String seedSession=java.util.UUID.nameUUIDFromBytes(getIntent().getStringExtra("dayflow_session").getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();boolean firstSeed=state==null&&!getPreferences(0).getString("seed_started","").equals(seedSession);if(seed!=null&&!seed.isEmpty()&&firstSeed){getPreferences(0).edit().putString("seed_started",seedSession).commit();engine.clear();messages.removeAllViews();while(transcript.length()>0)transcript.remove(0);bubble("资料整理","本轮生成的日程先进入收集箱，课表先生成表格草稿，必须人工核验后导入。");input.setText(seed);input.post(this::send);}
  worker.execute(()->{try{JSONObject ledger=engine.call("assistant_status",new JSONObject()).getJSONObject("created");runOnUiThread(()->{if(closed)return;Iterator<String> ids=ledger.keys();while(ids.hasNext())created.add(ids.next());undo.setEnabled(!created.isEmpty());});}catch(Exception e){showError(e);}});
 }
 private void send(){if(busy)return;String value=input.getText().toString().trim();if(value.isEmpty())return;input.setText("");bubble("你",value);setBusy(true,"正在理解并调用工具…");worker.execute(()->{try{engine.send(value,new ChatEngine.Listener(){public boolean active(){return !closed&&!Thread.currentThread().isInterrupted();}public void message(String text){runOnUiThread(()->{if(!closed)bubble("助手",text);});}public void tool(String name,JSONObject result){runOnUiThread(()->{if(closed)return;if(result.has("error")){bubble("工具未完成",result.optString("error"));return;}if(result.has("staged_course_count")){bubble("课表待核验","已生成 "+result.optInt("staged_course_count")+" 门课程草稿，点击返回人工核验，校正表格后再创建。");}else if(result.optBoolean("created")){created.add(result.optString("id"));String time=result.optString("start_at",result.optString("due_date"));if(time.length()>=10)resultDate=time.substring(0,10);String label=result.optString("confirmation_status").equals("pending")?"待人工核验":"已创建";bubble(label,result.optString("title")+(time.isEmpty()?"":"\n"+time.replace('T',' '))+(result.optString("location").isEmpty()?"":"\n"+result.optString("location")));}else if(result.has("items"))status.setText("已查询 "+result.optJSONArray("items").length()+" 条摘要，正在整理…");});}});}catch(Exception e){showError(e);}finally{runOnUiThread(()->{if(!closed){setBusy(false,"已执行操作以结果卡片为准");persist();}});}});}
 private void undo(){if(busy||created.isEmpty())return;JSONArray ids=new JSONArray(new ArrayList<>(created));setBusy(true,"正在撤销…");worker.execute(()->{try{JSONObject result=engine.call("assistant_undo",new JSONObject().put("ids",ids));runOnUiThread(()->{if(closed)return;created.clear();JSONArray skipped=result.optJSONArray("skipped");bubble("撤销结果","撤销 "+result.optInt("undone")+" 项"+(skipped!=null&&skipped.length()>0?"；已被编辑或不可撤销的 "+skipped.length()+" 项保留，请回日栖核对":""));});}catch(Exception e){showError(e);}finally{runOnUiThread(()->{if(!closed)setBusy(false,"");});}});}
 private void voice(){if(busy)return;try{startActivityForResult(new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_LANGUAGE,"zh-CN").putExtra(RecognizerIntent.EXTRA_PROMPT,"描述你想安排的事，识别后可修改"),2);}catch(ActivityNotFoundException e){bubble("语音","手机未安装可用的语音识别服务，可用键盘麦克风或直接打字。");}}
 protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==2&&result==RESULT_OK&&data!=null){ArrayList<String> values=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(values!=null&&!values.isEmpty()){input.setText(values.get(0));input.setSelection(input.length());}}}
 private void setBusy(boolean value,String label){busy=value;send.setEnabled(!value);voice.setEnabled(!value);undo.setEnabled(!value&&!created.isEmpty());status.setText(label);}
 private void showError(Exception e){runOnUiThread(()->{if(!closed)bubble("未完成",(e.getMessage()==null?"请求失败":e.getMessage())+"\n已经成功创建的事项保留，请核对结果后再重试。");});}
 private void bubble(String who,String value){try{transcript.put(new JSONObject().put("who",who).put("text",value));while(transcript.length()>80)transcript.remove(0);}catch(Exception ignored){}addBubble(who,value);}
 private void addBubble(String who,String value){TextView item=text(who+"\n"+value,16);item.setTextIsSelectable(true);item.setPadding(dp(14),dp(12),dp(14),dp(12));android.graphics.drawable.GradientDrawable background=new android.graphics.drawable.GradientDrawable();background.setColor(color(who.equals("你")?com.google.android.material.R.attr.colorSecondaryContainer:com.google.android.material.R.attr.colorSurfaceContainerLow));background.setCornerRadius(dp(16));item.setBackground(background);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(6),0,dp(6));messages.addView(item,p);while(messages.getChildCount()>80)messages.removeViewAt(0);scroll.post(()->scroll.fullScroll(View.FOCUS_DOWN));}
 private void persist(){try{android.util.AtomicFile file=new android.util.AtomicFile(new File(getCacheDir(),"assistant-chat.json"));FileOutputStream out=null;try{out=file.startWrite();out.write(new JSONObject().put("history",new JSONArray(engine.snapshot())).put("transcript",transcript).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);}}catch(Exception ignored){}}
 private void load(){try(InputStream in=new FileInputStream(new File(getCacheDir(),"assistant-chat.json"))){JSONObject saved=new JSONObject(ChatEngine.read(in));engine.restore(saved.getJSONArray("history").toString());JSONArray log=saved.getJSONArray("transcript");for(int i=Math.max(0,log.length()-80);i<log.length();i++){JSONObject r=log.getJSONObject(i);transcript.put(r);addBubble(r.optString("who"),r.optString("text"));}}catch(Exception ignored){}}
 protected void onDestroy(){closed=true;worker.shutdownNow();super.onDestroy();}
 private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}private int color(int attr){return MaterialColors.getColor(this,attr,0xff386a5c);}private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}private LinearLayout row(){LinearLayout l=column();l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color(com.google.android.material.R.attr.colorOnSurface));return t;}private MaterialButton button(String label,Runnable action){MaterialButton b=new MaterialButton(this,null,com.google.android.material.R.attr.materialButtonOutlinedStyle);b.setText(label);b.setSingleLine(true);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(4),0,dp(4),0);b.setOnClickListener(v->action.run());return b;}
}
